class Gym {
  + ComputeMonthlyBalance(m : int, y : int) : int
  + ComputeAnnualBalance(y : int) : int
  + SendArrearsReminders()
  + SendMedicalCheckReminders()
}

class Customer {
  + name : string
  + surname : string
  + age : int
  + address : string
  + profession : string
}

class Subscription {
  + Income(d : date) : int
}

class MonthlySubscription extends Subscription {
  + MonthlyCost() : int
}

class AnnualSubscription extends Subscription {
  + MonthlyCost() : int
}

class Service {
}

class BaseService extends Service {
}

class AdditionalService extends Service {
}

class WorkoutPlan {
}

class Exercise {
}

class WorkoutPlanExercise {
  + repetitions : int
  + frequency : int
}

class MedicalCheckResult {
  + weight : float
  + bodyFat : float
  + electrocardiogram : string
  + restingHeartbeat : int
  + stressHeartbeat : int
}

class MedicalStaff {
}

Customer "1" -- "1" WorkoutPlan
Customer "1" -- "1..*" Subscription
Customer "0..1" -- "0..*" MedicalCheckResult
Customer "0..*" -- "0..*" Service
Gym "1" -- "0..*" Subscription
Gym "1" -- "0..*" Service
Gym "1" -- "0..*" MedicalStaff
MedicalStaff "1" -- "0..*" MedicalCheckResult
WorkoutPlan "1" -- "1..*" WorkoutPlanExercise
WorkoutPlanExercise "0..*" -- "1" Exercise

@enduml

